const trace = (x: unknown): void => {

	if (traceFlag) {
		if (isString(x)) {
			console.log(yellow(x))
		}
		else if ((typeof x === 'object') && (x !== null)) {
			console.log(x.toString())
		}
		else {
			console.log(x)
		}
	}
	return
}

